#' Phase_distribution
#'
#' @description Generates a graph of gene phase distributions.
#' 
#' @param dryList A DryR list containing dataframes with results, rhythmic parameters, normalized counts, raw counts, and the Cook's distance produced by the dryseq() function. It is an object generated by DryR containing the expression models.
#' 
#' @return A histogram of each selected condition.
#' @export

Phase_distribution <- function(dryList) {
  ggpubr::ggarrange(
    plotlist = list(
      # CTRL Ad Libitum
      ggplot(
        dryList$results |>
          rownames_to_column("gene_name") |>
          select(gene_name, contains("phase_")) |>
          filter(!is.na(phase_CTRL) |
                   !is.na(phase_RF)) |>
          mutate(rhythmic_in = ifelse(
            !is.na(phase_CTRL) & !is.na(phase_RF),
            "both",
            ifelse(!is.na(phase_CTRL), "CTRL", "RF")
          )) |>
          filter(rhythmic_in %in% c("CTRL", "both")),
        aes(
          x = phase_CTRL,
          y = after_stat(count),
          fill = rhythmic_in
        )
      ) +
        geom_histogram(
          bins = 24,
          breaks = seq(0, 24, by = 1),
          position = "identity"
        ) +
        scale_fill_manual(values = c("#007FFF", "grey70")) +
        xlab(label = "acrophase (ZT)") +
        scale_y_continuous(expand = c(0, 0), limits = c(0, 400)) +
        ylab(label = "genes counts") +
        scale_x_continuous(
          breaks = seq(4, 24, 4),
          expand = c(0, 0),
          limits = c(0, 24)
        ) +
        theme_classic() +
        ggtitle(label = "AdLib") +
        theme(
          legend.position = "none",
          plot.title = element_text(hjust = 0.5)
        )
      ,
      # DTF
      ggplot(
        dryList$results |>
          rownames_to_column("gene_name") |>
          select(gene_name, contains("phase_")) |>
          filter(!is.na(phase_CTRL) |
                   !is.na(phase_RF)) |>
          mutate(rhythmic_in = ifelse(
            !is.na(phase_CTRL) & !is.na(phase_RF),
            "both",
            ifelse(!is.na(phase_CTRL), "CTRL", "RF")
          )) |>
          filter(rhythmic_in %in% c("RF", "both")),
        aes(
          x = phase_RF,
          y = after_stat(count),
          fill = rhythmic_in
        )
      ) +
        geom_histogram(
          bins = 24,
          breaks = seq(0, 24, by = 1),
          position = "identity"
        ) +
        scale_fill_manual(values = c("#FF7F00", "grey70")) +
        xlab(label = "acrophase (ZT)") +
        scale_y_continuous(expand = c(0, 0), limits = c(0, 400)) +
        ylab(label = "genes count") +
        scale_x_continuous(
          breaks = seq(4, 24, 4),
          expand = c(0, 0),
          limits = c(0, 24)
        ) +
        theme_classic() +
        ggtitle(label = "DTF") +
        theme(
          legend.position = "none",
          plot.title = element_text(hjust = 0.5)
        )
    ),
    ncol = 2
  )
}
